ST.xhtml:
statuses.initializationStatus();
statuses.healthStatus(
    isGood := processes.initialize.statuses.healthStatus.isGood AND (processes.changeOperatingState.statuses.healthStatus.isGood AND (processes.slewToCoordinates.statuses.healthStatus.isGood AND (processes.slewToAziEle.statuses.healthStatus.isGood AND (processes.abortSlew.statuses.healthStatus.isGood AND (processes.powerOn.statuses.healthStatus.isGood AND (processes.powerOff.statuses.healthStatus.isGood AND (processes.moveKnownPosition.statuses.healthStatus.isGood AND processes.setTracking.statuses.healthStatus.isGood))))))),
    hasWarning := processes.initialize.statuses.healthStatus.hasWarning OR (processes.changeOperatingState.statuses.healthStatus.hasWarning OR (processes.slewToCoordinates.statuses.healthStatus.hasWarning OR (processes.slewToAziEle.statuses.healthStatus.hasWarning OR (processes.abortSlew.statuses.healthStatus.hasWarning OR (processes.powerOn.statuses.healthStatus.hasWarning OR (processes.powerOff.statuses.healthStatus.hasWarning OR (processes.moveKnownPosition.statuses.healthStatus.hasWarning OR processes.setTracking.statuses.healthStatus.hasWarning))))))));
statuses.busyStatus( isBusy := processes.initialize.statuses.busyStatus.busy OR (processes.changeOperatingState.statuses.busyStatus.busy OR (processes.slewToCoordinates.statuses.busyStatus.busy OR (processes.slewToAziEle.statuses.busyStatus.busy OR (processes.abortSlew.statuses.busyStatus.busy OR (processes.powerOn.statuses.busyStatus.busy OR (processes.powerOff.statuses.busyStatus.busy OR (processes.moveKnownPosition.statuses.busyStatus.busy OR processes.setTracking.statuses.busyStatus.busy))))))) );
statuses.operatingStatus( superState := statuses.initializationStatus.initialized );
statuses.poweredStatus();
processes.initialize( isEnabled := (NOT(statuses.initializationStatus.locked)) AND (statuses.initializationStatus.shutdown OR (statuses.initializationStatus.initializingFailed OR statuses.initializationStatus.initialized)) );
processes.lock( isEnabled := operatorStatus.tech );
processes.unlock( isEnabled := operatorStatus.tech AND statuses.initializationStatus.locked );
processes.changeOperatingState( isEnabled := statuses.busyStatus.idle AND (statuses.initializationStatus.initialized AND operatorStatus.tech) );
processes.slewToCoordinates( isEnabled := statuses.initializationStatus.initialized AND (statuses.busyStatus.idle AND statuses.poweredStatus.enabled) );
processes.slewToAziEle( isEnabled := statuses.initializationStatus.initialized AND (statuses.busyStatus.idle AND statuses.poweredStatus.enabled) );
processes.abortSlew( isEnabled := statuses.initializationStatus.initialized );
processes.reset( isEnabled := statuses.busyStatus.idle AND statuses.initializationStatus.initialized );
processes.powerOn( isEnabled := (NOT(statuses.initializationStatus.locked)) AND (statuses.initializationStatus.initialized AND processes.powerOn.statuses.busyStatus.idle) );
processes.powerOff( isEnabled := statuses.initializationStatus.initialized AND processes.powerOff.statuses.busyStatus.idle );
processes.moveKnownPosition( isEnabled := statuses.initializationStatus.initialized AND (statuses.busyStatus.idle AND statuses.poweredStatus.enabled) );
processes.setTracking( isEnabled := statuses.initializationStatus.initialized );

slewToCoordinates := THIS^.processes.slewToCoordinates.request(
    alpha := alpha,
    delta := delta);

slewToAziEle := THIS^.processes.slewToAziEle.request(
    azimuth := azimuth,
    elevation := elevation);

IF do_request THEN
    do_request_result := request(
    alpha := set.alpha,
    delta := set.delta);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.alpha := alpha;
THIS^.get.delta := delta;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        alpha := alpha,
        delta := delta);
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request(
    azimuth := set.azimuth,
    elevation := set.elevation);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.azimuth := azimuth;
THIS^.get.elevation := elevation;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        azimuth := azimuth,
        elevation := elevation);
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request( tracking := set.tracking );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.tracking := tracking;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( tracking := tracking );
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request( name := set.name );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.name := name;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( name := name );
ELSE
    request := RequestResults.REJECTED;
END_IF;
